window.__BUNDLE__={"generatedAt":"2026-11-05T11:29:27.166505+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-10-29","archiveCutoff":"2021-11-06","addedToday":318,"addedThisRun":318,"fetchStats":{"hf":286,"arxiv":1498,"total":1784},"freshness":{"latestPaperDate":"2026-11-05","latestPublishedDate":"2026-11-05","latestBatchCount":281,"newInLast24h":662,"newInLast48h":662},"historyTotal":30576,"topicCounts":{"Multi-Agent":3199,"Evaluation":16811,"Planning":2234,"Memory":600,"Code Agent":1231,"Interpretability":1014,"Agentic RAG":1585,"Agentic Search":2131,"RL for LLM":1603,"Reasoning":8119,"Hallucination":1320,"Post-Training":3366,"Alignment":3945,"World Model":612,"Tool Use":1483,"Agent Safety":2776,"Computer Use":406,"Reflection":1086,"VLM Training":2420,"LLM Training":3933,"Fine-tuning":4767,"Multimodal Agent":178,"Agent Framework":980,"Error Attribution":190,"Data Engine":609},"count":36,"recentTotal":2219,"archiveCount":0,"archiveTotal":28357,"sources":{"hf":52,"arxiv":2167,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Reasoning","Fine-tuning"],"upvotes":50,"source":"hf","id":"arxiv:2611.06918","title":"From Pixels to Actions - Towards Native Vision-Language-Action Policies","url":"https://arxiv.org/abs/2611.06918","tags":["Reasoning","Fine-tuning"],"hfUrl":"https://huggingface.co/papers/2611.06918","date":"2026-11-05","authors":["Weichen Fan","Haiwen Diao","Penghao Wu","Siyuan Hu","Ziqi Huang","Tianqi Liu","Mingze Sun","Ziyi Wang","Zhongang Cai","Hanming Deng","Quan Wang","Lei Yang","Lewei Lu","Fangzhou Hong","Zhaoxi Chen","Dahua Lin","Ziwei Liu"],"pdf":"https://arxiv.org/pdf/2611.06918.pdf","arxiv":"https://arxiv.org/abs/2611.06918","abstract":"Vision-language-action models are typically built on a simple premise: perception is first compressed by visual encoders, and action reasoning begins only afterwards. Yet manipulation often hinges on precisely the visual signals most vulnerable to this abstraction, e.g., local geometry, boundaries, depth, and subtle state changes. This raises a fundamental question: should action policies inherit a fixed visual endpoint, or directly access evolving visual computation? We introduce NEO-VLA, a structurally encoder-free vision-language-action framework. Images are tokenized by lightweight patch convolutional layers and evolve jointly with language throughout the backbone, allowing a flow-matching action expert to draw from instruction-conditioned visual representations at different depths. This simple change reveals a consistent pattern. Native architectures outperform encoder-based counter"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Reasoning","Evaluation"],"upvotes":26,"source":"hf","id":"arxiv:2611.06910","title":"FrontierPhysics: Evaluating Agents for End-to-End Physics Research","url":"https://arxiv.org/abs/2611.06910","tags":["Reasoning","Evaluation"],"hfUrl":"https://huggingface.co/papers/2611.06910","date":"2026-11-05","authors":["Bingran You","Wenjun Ke","Ria Rosenauer","Bo Liu","Wenbo Chen","Min Chen","Shuqi Xu","Yue Ma","Jiechao Feng","Bo Chen","Xiangkai Sun","Jiarui Liu","Jinen Guo","Zeyu Zhou","Xu Huang","Zhuohan Li","Haoyu Li","Heguang Lin","Lijie Ding","Yadong Zeng","Kangqi Zhang","Xinge Liu","Hanwen Liu","Zhenghong Li","Alexander von Recum","Yuchen Zhu","Felix Schwarzfischer","Yizhou Zhao","Jicheng Wang","Binxu Li","Qian Yu","Chan Li","Cheng Dai","Di Wang","Haoyu Zhang","Jiankai Sun","Kaituo Feng","Mian Qin","Ruihong Yin","Yiqun Luo","Weiwei Wu","Shihong Pan","Tsung Yeh Hsieh","Xiao Huang","Yan Zhang","Sihan Li","Zirui Ren","Zengji Tu","Kyoung Whan Choe","Ke Sun","Vincenzo Galia","Vaisakhi Mishra","Jiashu He","Hongyang Wang","Zhiheng Yang","Shubham Gaur","Yifan Gu","Shuyi Wang","Zihao Zuo","Steven Dillmann","Yiyou Sun","Xinyang Han","Hanchung Lee","Molei Tao","Yue Zhao","Shilong Liu","Yuchen Wu","Xuandong Zhao","Xiangyi Li","Florian Brand","Gerbrand Ceder","Hartmut Haeffner"],"pdf":"https://arxiv.org/pdf/2611.06910.pdf","arxiv":"https://arxiv.org/abs/2611.06910","abstract":"AI agents are playing an increasingly important role in physics research. However, existing physics benchmarks only evaluate fixed questions, isolated sub-tasks, or paper reproduction with given solutions, and rarely check research quality alongside correctness. We introduce FrontierPhysics, an end-to-end benchmark with 56 tasks made by 42 physicists based on their own research, covering nine domains across theoretical, computational, and experimental physics. Each task requires agents to review the literature, develop a research plan, conduct research and experiments, and produce structured outputs and scientific manuscripts. Combining deterministic verifiers with expert-authored rubrics, FrontierPhysics evaluates whether agents' research is correct and publishable. Across 22 models in 26 configurations, no configuration passes more than 46 of its 168 rollouts. Manual review of agent tr"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Post-Training"],"upvotes":25,"source":"hf","id":"arxiv:2611.06728","title":"Turns Matter: Advancing Streaming Video RL via Turn-Level Credit","url":"https://arxiv.org/abs/2611.06728","tags":["Post-Training"],"hfUrl":"https://huggingface.co/papers/2611.06728","date":"2026-11-05","authors":["Shuai Dong","Kanghui Tian","Linghan Chen","Wenqi Shao","Hongrui Wu","Haowen Hou","Yongfu Zhu","Xuehui Wang","Ziyue Wang","Wenpu Liu","Weichu Xie","Yuqi Xu","Congcong Wang","Kaiwen Tuo","Caoyuan Ma","Taiqiang Wu","Ji Zhao","Wenzheng Chang","Dianyi Wang","Siyuan Wang","Zhongyu Wei","Yu Qiao","Jiaqi Wang"],"pdf":"https://arxiv.org/pdf/2611.06728.pdf","arxiv":"https://arxiv.org/abs/2611.06728","abstract":"Streaming video understanding requires models to repeatedly decide whether to respond or continue observing. Recently, Group Relative Policy Optimization (GRPO) has been applied to this setting, with existing approaches emphasizing reward design while retaining a single trajectory-level advantage across turns. Such shared credit can reinforce redundant replies after earlier successes and discourage useful follow-ups after earlier failures. We propose TurnWise, a turn-level GRPO framework that aligns learning with individual streaming decisions. TurnWise addresses the mismatch between trajectory-level feedback and turn-level interaction, promoting informative responses and reducing redundancy. Specifically, turn-level credit assignment uses silence-completed prefix scoring to construct group-relative advantages from each decision's remaining return, separating its learning signal from ear"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["RL for LLM"],"upvotes":24,"source":"hf","id":"arxiv:2611.06483","title":"What Does Multi-Turn Reinforcement Learning Really Improve in LLM Agents?","url":"https://arxiv.org/abs/2611.06483","tags":["RL for LLM"],"hfUrl":"https://huggingface.co/papers/2611.06483","date":"2026-11-05","authors":["Kejian Zhu","Zhuoran Jin","Shangqing Tu","Tianyi Men","Yupu Hao","Jiachun Li","Kang Liu","Jun Zhao"],"pdf":"https://arxiv.org/pdf/2611.06483.pdf","arxiv":"https://arxiv.org/abs/2611.06483","abstract":"While multi-turn agentic reinforcement learning (RL) excels on long-horizon tasks, its performance gains remain highly sensitive to interaction constraints. Evaluating across sampling breadth $K$ and interaction depth $T$ via $Pass@(K,T)$, we show that trajectory-level RL advantages depend on sufficient turn budgets, diminishing significantly when budgets tighten. Besides, agentic RL does not uniformly elevate single-step decision quality; rather, its strength concentrates in error recovery and long-horizon resilience. To mitigate the deployment risks caused by this budget dependence, we provide a preliminary discussion on the benefits and limitations of process supervision signals and introduce BudgetMix RL as an alternative that varies interaction budgets during training. Experiments demonstrate that BudgetMix RL achieves robust performance across diverse execution settings. Project Pa"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Post-Training","Evaluation","Alignment"],"upvotes":18,"source":"hf","id":"arxiv:2611.06518","title":"EmoReward: Self-Evolving Reward Calibration for Emotional Video Generation RL","url":"https://arxiv.org/abs/2611.06518","tags":["Post-Training","Evaluation","Alignment"],"hfUrl":"https://huggingface.co/papers/2611.06518","date":"2026-11-05","authors":["Mingzhe Zheng","Yue Wu","Jing Tan","Chang Zou","Dengyang Jiang","Zeyue Tian","Xuanhua He","Ryan Xu","Yunyang Ge","Sihui Ji","Yunlong Lin","Kaihang Pan","Hongru Yan","Sixiang Chen","Dianyi Wang","Julian Zhang","Weijie Kong","Changlin Li","Lanqing Guo","Zhao Zhong","Qifeng Chen","Harry Yang"],"pdf":"https://arxiv.org/pdf/2611.06518.pdf","arxiv":"https://arxiv.org/abs/2611.06518","abstract":"Group Relative Policy Optimization (GRPO) has advanced generative model post-training in verifiable domains such as code and mathematics, but evaluating video quality, especially emotional expression, often depends on subjective aesthetics and has no uniquely correct target. Existing approaches typically rely on fixed rewards for visual quality, motion quality, and text alignment that poorly capture emotional intent and can invite reward hacking, while RLHF is difficult to scale and subject to individual aesthetic differences that complicate the calibration of facial, body motion, and chromatic cues across narrative contexts. We introduce EmoReward, a new self-evolving training mechanism that distills evidence reliability from reward traces collected during an actual training run to adaptively guide multi-reward weight allocation in subsequent training by determining which emotional evid"},{"topics":["Agent Safety","Reasoning","Code Agent","Evaluation","Reflection"],"upvotes":4,"source":"hf","id":"arxiv:2611.06768","title":"PyRUA-REAL: Robot Exploration and Adaptive Learning through RSI in the Real World","url":"https://arxiv.org/abs/2611.06768","tags":["Agent Safety","Reasoning","Code Agent","Evaluation","Reflection"],"hfUrl":"https://huggingface.co/papers/2611.06768","date":"2026-11-05","authors":["Qiang Wang","Jianxin Bi","Shulong Jiang","Ruiyang Si","Wenbo Huang","Kaiqi Chen","Jiaxin Li","Liyun Li","Xuanyi Li","Daquan Zhou"],"pdf":"https://arxiv.org/pdf/2611.06768.pdf","arxiv":"https://arxiv.org/abs/2611.06768","abstract":"Coding agents powered by models such as GPT-6-Astra connect spatial reasoning with executable robot behavior, raising the question of how such agents can produce lasting improvements in robot capabilities from physical interaction. In this work, we study embodied recursive self-improvement (RSI) through real-world exploration, code refinement, and deployment using PyRUA-REAL, a framework in which coding agents retain interaction experience as persistent memory and reusable executable skills that inform subsequent exploration and improvement. Our empirical study places physical manipulation at the center of the improvement process, examining how agents collaborate, what kinds of execution feedback support effective code refinement, and how task specifications and previously acquired skills influence robustness and task transfer. We further investigate the efficiency and capability of the "},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["LLM Training","VLM Training","Evaluation","Alignment"],"upvotes":4,"source":"hf","id":"arxiv:2611.06083","title":"SleuthVLM: Do We Really Need Audio-in-Video for Omni Video Understanding?","url":"https://arxiv.org/abs/2611.06083","tags":["LLM Training","VLM Training","Evaluation","Alignment"],"hfUrl":"https://huggingface.co/papers/2611.06083","date":"2026-11-05","authors":["Peiran Wu","Fangfei Gou","Zhaoxi Mu","Changhao Zhang","Jian Liu","Weiqiang Wang","Yuntao Wang","Yuanchun Shi","Junxiao Shen"],"pdf":"https://arxiv.org/pdf/2611.06083.pdf","arxiv":"https://arxiv.org/abs/2611.06083","abstract":"Omni models answer questions about videos by jointly processing sampled frames and audio in one turn, with progress driven largely by scaling model size and omni training data. We ask whether a model needs to hear the audio directly at all, and present SleuthVLM, an agent harness built on a VLM that never hears the audio directly: speech will be transcribed into text, and the VLM will sleuth the video on its own without any predefined workflow. On four omni benchmarks with videos up to 90 minutes, SleuthVLM achieves the best average accuracy: \\textbf{75.0%}, 2.6 points above Gemini 3.8 Flash, and it also tops the Video-MME-v2 leaderboard with \\textbf{77.8%}; with an open-source 27B VLM, it beats all open-source omni models. We draw three findings: SleuthVLM beats a model that glances; hearing is not the bottleneck, agentic ability is; omni understanding needs better agentic ability, not "},{"announceDate":"2026-11-05","submittedDate":"2026-11-03","topics":["Reasoning"],"upvotes":2,"source":"hf","id":"arxiv:2611.05609","title":"On the Generalization Limitation of On-Policy Distillation for Post-RL Consolidation","url":"https://arxiv.org/abs/2611.05609","tags":["Reasoning"],"hfUrl":"https://huggingface.co/papers/2611.05609","date":"2026-11-05","authors":["Yichen Wang","Yufa Zhou","Siqi Zhu","Haozheng Luo","Jingzhi Bao","Zhichao Liu","Zijun Wei"],"pdf":"https://arxiv.org/pdf/2611.05609.pdf","arxiv":"https://arxiv.org/abs/2611.05609","abstract":"Multi-teacher on-policy distillation (MOPD) extends on-policy distillation (OPD) to consolidate capabilities from multiple teachers. Although prior work reports near-perfect in-distribution (IND) distillation performance, we find that this can mask incomplete capability consolidation beyond the supervised distribution. A preliminary study on synthetic reasoning shows that OPD does not fully transfer teachers' generalization capabilities. We then extend this investigation to real-world tasks, evaluating extrapolative and compositional generalization across mathematical reasoning, coding, agent, and long-context capabilities using Qwen3 models. Across extrapolative settings, OPD and MOPD reach 96.04-102.73% of their teachers' IND scores. Yet their out-of-distribution (OOD) scores remain 2.45-16.25% below the base model's. Across three compositional settings, MOPD improves IND performance o"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Agentic Search","LLM Training","Reasoning","Evaluation","Fine-tuning","Multimodal Agent"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06131","title":"ModalSearcher: Weaving Visual Evidence into Autonomous Cross-Modal Deep Search","url":"https://arxiv.org/abs/2611.06131","tags":["Agentic Search","LLM Training","Reasoning","Evaluation","Fine-tuning"],"date":"2026-11-05","authors":["Zhihan Yin","Ruyi Li","Chengyu Fang","Yifeng Yao","Nonghai Zhang","Pengfei Xiong","Terry Zhang","Huishuai Zhang","Dongyan Zhao"],"pdf":"https://arxiv.org/pdf/2611.06131.pdf","arxiv":"https://arxiv.org/abs/2611.06131","abstract":"Static and incomplete parametric knowledge limits the performance of multimodal large language models on novel-knowledge and knowledge-intensive tasks, especially those requiring multi-hop evidence acquisition. Existing multimodal agentic search methods often fix visual evidence at the input or a predefined trajectory position, making it difficult for agents to select search modalities as their information needs evolve and to handle complex real-world queries. We define this capability as autonomous cross-modal search: an agent chooses among direct reasoning, text-to-text search, text-to-image search, and reverse-image search, actively introduces visual evidence when appropriate, and switches between and integrates modalities across multiple hops. We propose ModalSearch-Pipeline, a scalable procedure for constructing an interleaved multimodal knowledge graph. It samples paths with divers"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Post-Training","VLM Training","Reasoning","Hallucination","Alignment","Fine-tuning"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06302","title":"Beyond Scene Shortcuts: Action-Centric Video-Text Alignment for Fine-Grained Action Understanding","url":"https://arxiv.org/abs/2611.06302","tags":["Post-Training","VLM Training","Reasoning","Hallucination","Alignment"],"date":"2026-11-05","authors":["Zhiliang Zhu","Jiazheng Huang","Dawei Zhao"],"pdf":"https://arxiv.org/pdf/2611.06302.pdf","arxiv":"https://arxiv.org/abs/2611.06302","abstract":"Fine-grained action understanding requires vision-language models to ground what an agent does, how it acts, and why it acts in spatio-temporal evidence. However, richer supervision can backfire: fine-tuned models may generate detailed action descriptions grounded in static scenes and salient objects rather than motion, a failure we call Environment-Grounded Action Hallucination (EGAH). To mitigate EGAH, we propose Staged Attention Rectification and Reinforcement (STARR), an action-centric video-text alignment framework that breaks scene-action shortcuts through Action-Environment Dissociation and reinforces action-focused grounding with an Attention Consistency Reward within Group Relative Policy Optimization. We further construct FineActionR&R, combining temporally localized captions with hierarchical and temporal-causal reasoning data. Built on Qwen2.5-VL-7B, FineActionVLM-R1 improves"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Agent Safety","Multi-Agent","Tool Use","Reasoning","Reflection"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06389","title":"MA-Mesh: Resilient Multi-Agent Collaboration via Role-based Self-Healing","url":"https://arxiv.org/abs/2611.06389","tags":["Agent Safety","Multi-Agent","Tool Use","Reasoning","Reflection"],"date":"2026-11-05","authors":["JunYong Lee","Woo Kyung Kim","Honguk Woo"],"pdf":"https://arxiv.org/pdf/2611.06389.pdf","arxiv":"https://arxiv.org/abs/2611.06389","abstract":"Effective collaboration in multi-agent systems requires mechanisms for coordination and adaptability in dynamic and uncertain environments. However, existing multi-agent systems rarely model resilience explicitly, instead relying on ad-hoc output correction that limits systematic, runtime management of robustness. In this work, we propose Multi-Agent Mesh (MA-Mesh), a framework that constructs a role-based self-healing layer on top of a collaboration pattern. Specifically, MA-Mesh generates resilience-aware system specifications and synthesizes them into executable multi-agent policy code. To enhance resilience, we introduce two self-healing mechanisms: Cross-agent reflection, a mechanism that allows agents to evaluate not only their own outcomes but also the performance of their peers, enabling informed behavioral adjustments and collective policy refinement; Role-based failover, a stra"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Agentic RAG","Agentic Search","LLM Training","Reasoning","Evaluation"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06715","title":"Reasoning over Non-Parametric Memory in Multilingual LLMs: A Cognitive-Based Analysis of Relational Knowledge","url":"https://arxiv.org/abs/2611.06715","tags":["Agentic RAG","Agentic Search","LLM Training","Reasoning","Evaluation"],"date":"2026-11-05","authors":["Zohreh Abbasi Liasi","Batoul Hammoud","Anas Madkoor","Ehsaneddin Asgari"],"pdf":"https://arxiv.org/pdf/2611.06715.pdf","arxiv":"https://arxiv.org/abs/2611.06715","abstract":"Retrieval-augmented generation (RAG) assumes that language models can reason over relations stated in their context rather than fall back on associations memorized during pretraining. We study this evidence-conditioned relational reasoning in isolation, with the facts supplied directly in the prompt rather than retrieved. \\textsc{Rel-Bloom} is a controlled multilingual diagnostic of 450 multiple-choice questions built from 30 Wikidata relations; the same source relations are instantiated at five Bloom-inspired levels (Remember, Understand, Apply, Analyze, Evaluate) and under three veracity conditions (Factual, Counterfactual, Neutralized). Across 43 models, six languages, and two multilingual settings (226,800 predictions), three findings stand out. First, accuracy drops sharply from Apply to Analyze in every evaluated open-weight model series, reaching 47.2 percentage points for the Lar"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Agentic RAG","Agentic Search","LLM Training","Evaluation","Fine-tuning"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06170","title":"AssameseLM-E2B: An Open-Weight Assamese Language Model for Efficient Consumer-Grade Deployment","url":"https://arxiv.org/abs/2611.06170","tags":["Agentic RAG","Agentic Search","LLM Training","Evaluation","Fine-tuning"],"date":"2026-11-05","authors":["Pragyan Phukan"],"pdf":"https://arxiv.org/pdf/2611.06170.pdf","arxiv":"https://arxiv.org/abs/2611.06170","abstract":"While Large Language Models (LLMs) excel in high-resource languages, their performance often degrades in low-resource languages due to tokenization inefficiencies, generative instability, and linguistic interference. This paper presents AssameseLM-E2B and its instruction-tuned variant, AssameseLM-E2B-it, a 2-billion-parameter model adapted specifically for low resource Assamese language. Built upon the Gemma-4 architecture, the model incorporates an expanded byte-level BPE vocabulary to reduce tokenization overhead by nearly 500% compared with multilingual 2B--3B baselines. We employ a parameter-efficient Continual Pre-Training (CPT) pipeline with Hybrid LoRA, followed by Supervised Fine-Tuning (SFT) on a balanced, multi-domain dataset to enhance instruction-following and Retrieval-Augmented Generation (RAG) capabilities. Evaluation demonstrates a Bits-per-Byte (BPB) score of 0.7488 on F"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["LLM Training","VLM Training","Reasoning","Evaluation","Data Engine"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06040","title":"USI-Brain: Enhancing Underwater Spatial Intelligence via Spatial Data-Driven Vision-Language Modeling","url":"https://arxiv.org/abs/2611.06040","tags":["LLM Training","VLM Training","Reasoning","Evaluation","Data Engine"],"date":"2026-11-05","authors":["Zhiliang Zhu","Zhiqiang Zhao","Xie'an Jiang","Yingxin Lai","Kangye Zheng","Dawei Zhao"],"pdf":"https://arxiv.org/pdf/2611.06040.pdf","arxiv":"https://arxiv.org/abs/2611.06040","abstract":"Underwater spatial reasoning depends on object boundaries and geometric cues that are obscured by scattering, color distortion, and low visibility. Existing underwater resources capture these cues through images, annotations, and depth maps, but provide fragmented supervision for vision-language models. We present a spatial data engine that connects visual appearance with object-level geometry through enhancement, 2D and geometry-assisted question generation, and expert filtering. It produces 4.27M QA pairs across five capability groups. We use this corpus to train USI-Brain and introduce an Underwater Prior-guided Rectifier (UPR) that applies gated corrections to visual features. USI-Bench evaluates the resulting capabilities with 6,525 held-out QA pairs. On its 15 task metrics, USI-Brain and USI-Brain + UPR improve over Qwen3-VL-8B-Instruct by 5.76 and 7.63 points on average, respectiv"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Post-Training","LLM Training","VLM Training","Fine-tuning"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06123","title":"From Handcrafted to Generative: RLVR-Optimized Icon Generation for Alexa+","url":"https://arxiv.org/abs/2611.06123","tags":["Post-Training","LLM Training","VLM Training","Fine-tuning"],"date":"2026-11-05","authors":["Rohan Sequeira","Matthew Rosenberg","Amin Mahmoudabadbozchelou","Oleg Poliannikov","Jonathan Rubin"],"pdf":"https://arxiv.org/pdf/2611.06123.pdf","arxiv":"https://arxiv.org/abs/2611.06123","abstract":"Alexa+ devices with screens display animated icons during conversations to visually reinforce what is being said. The original set of these icons was hand-drawn by designers one at a time, a process that produces polished results but is time-consuming and cannot scale to the range of topics encountered in open-ended conversation. We describe an automated pipeline, deployed in production, that generates these vectorised animated icons from a text description alone and surfaces relevant animations to customers based on their ongoing conversation. The pipeline decomposes icon creation into a sequence of stages (image generation, semantic decomposition, vectorisation, styling, and animation). Its quality is determined at the very first of these, image generation, on which every downstream stage depends. We therefore focus on improving this first and most critical stage. Because the icons are"},{"announceDate":"2026-11-05","submittedDate":"2026-11-03","topics":["Agentic Search","Reasoning","Evaluation","Data Engine"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.05512","title":"SlackBench: Benchmarking Agents on Collaborative Projects Grounded in Real Code Repositories","url":"https://arxiv.org/abs/2611.05512","tags":["Agentic Search","Reasoning","Evaluation","Data Engine"],"date":"2026-11-05","authors":["Mingxuan Li","Huanzhi Mao","Ruitao Zheng","Jarod Stanbury James","Yunze Li","Natanya Anderson","Joseph E. Gonzalez","Alex Dimakis"],"pdf":"https://arxiv.org/pdf/2611.05512.pdf","arxiv":"https://arxiv.org/abs/2611.05512","abstract":"AI Agents are becoming digital coworkers that can browse the web, write code, run experiments, and assist humans over extended horizons. Yet existing benchmarks fall short of real knowledge work: many rely on synthetic data or isolated tasks, missing the complex, multi-party dynamics of collaborative projects, where critical information is scattered across conversations, code, and evolving decisions. Even simple workplace questions may require locating relevant channels and direct messages, recovering context from long discussions, inspecting repository state, reconciling stale or conflicting evidence, and synthesizing across sources. We introduce SlackBench, a benchmark for evaluating agents on realistic research and engineering workflows that require joint reasoning over workplace communication and evolving repository state. Grounded in privacy-preserving reenactments of real academic "},{"announceDate":"2026-11-05","submittedDate":"2026-11-03","topics":["Agent Safety","Multi-Agent","Planning","Evaluation"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.05524","title":"MA-SafeDiffuser: Safe Multi-Agent Planning with Diffusion Probabilistic Models","url":"https://arxiv.org/abs/2611.05524","tags":["Agent Safety","Multi-Agent","Planning","Evaluation"],"date":"2026-11-05","authors":["Kiran Ravish","Ankita Kushwaha","Preeti","Pawan Kumar"],"pdf":"https://arxiv.org/pdf/2611.05524.pdf","arxiv":"https://arxiv.org/abs/2611.05524","abstract":"We propose MA-SafeDiffuser, a multi-agent extension of SafeDiffuser that equips diffusion-based trajectory planners with finite-time diffusion invariance guarantees for joint-agent safety specifications. Building on the single-agent construction that embeds control barrier function (CBF) constraints into reverse-diffusion updates, we: (i) formalize joint safe sets as intersections of per-agent and pairwise barrier sets; (ii) derive centralized and decentralized (communication-aware) constrained denoising procedures with provable invariance under mild assumptions; (iii) address local-trap and deadlock phenomena via time-varying specifications and liveness CBFs; and (iv) develop a lightweight benchmarking suite including a multi-agent Maze2D domain. Empirically, MA-SafeDiffuser reduces violation counts relative to unconstrained diffusion baselines, while retaining planning quality. We prov"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Agentic Search","LLM Training","Reasoning","Evaluation"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06381","title":"LegalEvolver: Agentic Legal Judgment Prediction via Rubric-Guided Self-Evolution","url":"https://arxiv.org/abs/2611.06381","tags":["Agentic Search","LLM Training","Reasoning","Evaluation"],"date":"2026-11-05","authors":["Xinyu Yang","Jiejun Tan","Chenlong Deng","Chenghao Zhang","Tongyu Wen","Zhicheng Dou"],"pdf":"https://arxiv.org/pdf/2611.06381.pdf","arxiv":"https://arxiv.org/abs/2611.06381","abstract":"As LLM-based agents develop, they have been increasingly applied in the legal domain. Legal Judgment Prediction~(LJP) requires models to conduct multi-step reasoning and external legal evidence retrieval. Existing legal search agents' performance is often constrained by the quality of retrieval queries. They often formulate queries directly from the initial user request, overlooking latent legal issues and legally salient details. To address this issue, we propose \\emph{LegalEvolver}, a query optimization framework specifically designed to generate legally informative queries for LJP-oriented retrieval. Sampling high-quality optimized queries and their corresponding search trajectories is challenging, as relying solely on unguided high-temperature rollouts is both inefficient and constrained by the model's initial capabilities. We therefore heuristically optimize queries as seeds, improv"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Post-Training","Memory","Evaluation","Fine-tuning"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06445","title":"SUMONE: A Simple and Efficient Summarizer for Plug-and-Play Agent Memory","url":"https://arxiv.org/abs/2611.06445","tags":["Post-Training","Memory","Evaluation","Fine-tuning"],"date":"2026-11-05","authors":["Jizhe Zhang","Ang Li","Chenheng Zhang","Yisen Wang"],"pdf":"https://arxiv.org/pdf/2611.06445.pdf","arxiv":"https://arxiv.org/abs/2611.06445","abstract":"Long-horizon language-model agents accumulate increasingly large interaction histories, making context compaction essential for efficient execution. Existing learned compaction methods often rely on downstream task outcomes or solver behavior, coupling training to specific tasks or agents. We introduce SumOne, a standalone summarizer trained to preserve information in agent histories through masked reconstruction. Given a summary of the expired history, a frozen reconstructor recovers randomly masked portions of the original trajectory; reconstruction quality, combined with a length penalty, provides a task-agnostic reward for optimizing the summarizer with GRPO. This yields self-supervision directly from raw trajectories, without reference summaries or downstream task execution. At inference time, only the lightweight summarizer is retained, enabling plug-and-play context compression fo"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Reasoning","Planning","Evaluation","Reflection"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.05919","title":"Routes of Reasoning: Reading and Reshaping Test-Time Compute in MoE Models","url":"https://arxiv.org/abs/2611.05919","tags":["Reasoning","Planning","Evaluation","Reflection"],"date":"2026-11-05","authors":["Shengjie Wang","Mohsen Fayyaz","Nanyun Peng"],"pdf":"https://arxiv.org/pdf/2611.05919.pdf","arxiv":"https://arxiv.org/abs/2611.05919","abstract":"Reasoning models allocate test-time compute across distinct behaviors such as planning, deriving, and verifying. However, models frequently \"overthink,\" continuing to verify and re-derive long after finding a correct answer. This wastes expensive compute and can even degrade performance. Existing interventions, such as token budgets or steering, primarily regulate reasoning duration rather than targeting specific behaviors. In this work, we demonstrate that Mixture-of-Experts (MoE) routers provide a natural, training-free interface for behavioral control. We first split reasoning traces into sentence-level segments and label each with one of six reasoning behaviors (planning, execution, restatement, fact, reflection, and conclusion), so that every token carries the behavior of its segment. Linear probes on router logits predict this label nearly as well as probes on the residual stream, "},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Multi-Agent","Planning","Evaluation","Agent Framework"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.05911","title":"Autonomous agents for electricity-system planning","url":"https://arxiv.org/abs/2611.05911","tags":["Multi-Agent","Planning","Evaluation","Agent Framework"],"date":"2026-11-05","authors":["Yoon Pyo Lee","Samrendra Roy","Jay Phil Yoo","Kazuma Kobayashi","Souvik Chakraborty","Syed Bahauddin Alam"],"pdf":"https://arxiv.org/pdf/2611.05911.pdf","arxiv":"https://arxiv.org/abs/2611.05911","abstract":"Planning electricity systems requires repeated decisions that connect regional resources, investment, operation and network constraints. Here we present an autonomous planning framework that carries prepared regional scenarios through proposal, numerical evaluation, feedback interpretation, redesign and final plan selection. Agents propose investment bounds, storage operating conditions and feeder interventions, interpret numerical feedback, and decide how to revise designs and when to stop. The framework automatically executes annual investment-and-dispatch optimization and representative-feeder verification, applies fixed acceptance criteria and retains the lowest-cost accepted candidate. We evaluate forty carbon-constrained trajectories across ten system-year scenarios in five electricity systems and four countries, using two model deployments and single- and multi-agent architectures"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Agent Safety","Post-Training","Alignment","Interpretability"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06553","title":"Addition by Subtraction: Toward Mitigating Fragile Safety Alignment in Large Language Models","url":"https://arxiv.org/abs/2611.06553","tags":["Agent Safety","Post-Training","Alignment","Interpretability"],"date":"2026-11-05","authors":["Hamid Dashtbani","Alexandra Dmitrienko"],"pdf":"https://arxiv.org/pdf/2611.06553.pdf","arxiv":"https://arxiv.org/abs/2611.06553","abstract":"Large language models (LLMs) undergo safety alignment to prevent harmful generations, yet they remain vulnerable to jailbreak attacks. Recent work reveals a deeper structural weakness: safety alignment can be highly sparse, such that pruning a small number of safety-critical neurons or ablating a single refusal direction can substantially undermine aligned behavior. In this work, we take the first steps toward strengthening safety alignment such that it is less dependent on sparse model components. We propose Addition by Subtraction, which gradually removes identified safety-critical neurons during finetuning and uses preference optimization to re-establish safety-aligned behavior through other parts of the model. Our results show that the resulting models are substantially more robust to pruning-based attacks. Remarkably, these benefits generalize beyond the white-box attacks motivating"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["LLM Training","VLM Training","Evaluation","Fine-tuning"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06149","title":"Grounding in the Dark: Text-Only Training for Zero-Shot Video Temporal Localization","url":"https://arxiv.org/abs/2611.06149","tags":["LLM Training","VLM Training","Evaluation","Fine-tuning"],"date":"2026-11-05","authors":["Divyanshu Mishra","Sabine Sternig","Rakshith Shetty","Erhan Gundogdu"],"pdf":"https://arxiv.org/pdf/2611.06149.pdf","arxiv":"https://arxiv.org/abs/2611.06149","abstract":"Video-LLMs are typically trained on paired video-text data for temporal tasks, yet collecting precise temporal annotations and training on large-scale video datasets are both costly. We investigate whether a text-only LLM, with no vision-language pretraining, can be trained on textual video descriptions alone to perform temporal grounding and receive video only at inference time. This setting removes paired video data from training altogether and is a step toward training multimodal models without paired annotations. We generate a 134K-example corpus of textual sequences with up to 100 time steps, adapt Qwen3-8B with LoRA on CLIP or LLM2CLIP text embeddings, and evaluate on Charades-STA and QV-Highlights without training on videos from either benchmark. LLM2CLIP, whose text encoder supports longer inputs, represents detailed descriptions better than CLIP (61.54 versus 53.86 mtIoU on Temp"},{"announceDate":"2026-11-05","submittedDate":"2026-11-03","topics":["Post-Training","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.05515","title":"TSFM Meets LLM: Context as Covariates","url":"https://arxiv.org/abs/2611.05515","tags":["Post-Training","Reasoning","Evaluation","Fine-tuning"],"date":"2026-11-05","authors":["Hemanth Ram","Sai Shankar Narasimhan","Shubhankar Agarwal","Sandeep Chinchali"],"pdf":"https://arxiv.org/pdf/2611.05515.pdf","arxiv":"https://arxiv.org/abs/2611.05515","abstract":"Textual information is ubiquitous in real-world time series datasets, appearing as news, reports, and annotations that hold key predictive signals not deducible from numerical history alone. Large Language Models (LLMs) interpret text but lack numerical precision, while Time Series Foundation Models (TSFMs) are quantitatively accurate but cannot reason about the effects of text. Moreover, the lack of large-scale paired multimodal datasets limits progress in bridging this gap. In this work, we address this challenge by providing a scalable approach for generating realistic multimodal datasets by annotating real-world time series with LLMs. Building on this, we propose Context as Covariates (CoCo), a forecasting framework in which an LLM distills its textual reasoning into numerically grounded forecast and confidence covariates that guide a TSFM backbone, thereby exploiting the strengths o"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Reasoning","Evaluation","Fine-tuning","World Model"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.05890","title":"CellCanon: An Agentic Cellular World Model for Prediction, Explanation, and Observation-Driven Updating","url":"https://arxiv.org/abs/2611.05890","tags":["Reasoning","Evaluation","Fine-tuning","World Model"],"date":"2026-11-05","authors":["Zhaokang Liang","Shuyang Zhuang","Xiaoran Jiao","Hao Chen"],"pdf":"https://arxiv.org/pdf/2611.05890.pdf","arxiv":"https://arxiv.org/abs/2611.05890","abstract":"Biological discovery requires using molecular knowledge and new measurements to infer responses beyond the conditions already observed. We introduce CellCanon, the first agentic cellular world model to unify single-cell expression prediction, evidence-grounded explanation, and observation-driven updating. Its predictive core reuses condition-level biological evidence across gene-specific numerical readouts to guide single-cell expression generation. A shared world state links predictions, acquired measurements, and source-linked claims, supporting explanation and revision. On 339 held-out SciPlex3 conditions across three cell lines, CellCanon improves differential-expression AUPRC and Macro-F1 over the best baseline for each metric by 63.3% and 17.3%, respectively, and direction Macro-F1 by 7.2%. Relative to gene-wise reasoning on matched drug-cell cohorts, measured language-model token "},{"announceDate":"2026-11-05","submittedDate":"2026-11-02","topics":["Agentic RAG","Agentic Search","Memory","Reflection"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.05427","title":"LLM-based NPCs in Video Games: A Systematic Mapping Study","url":"https://arxiv.org/abs/2611.05427","tags":["Agentic RAG","Agentic Search","Memory","Reflection"],"date":"2026-11-05","authors":["Dilan Mian","Jeremy Bradbury","Yann-Gaël Guéhéneuc","Fabio Petrillo","Cristiano Politowski"],"pdf":"https://arxiv.org/pdf/2611.05427.pdf","arxiv":"https://arxiv.org/abs/2611.05427","abstract":"For decades, non-player characters (NPCs) have been driven by rule-based systems whose personalities and interactions are scripted before release. Large language models (LLMs) promise NPCs that converse openly, adapt to new situations, and behave in ways developers did not fully author, prompting a wave of research and commercial experimentation. Yet the field lacks a unified picture of what has been built, how well it works, and at what cost. We address this gap with a systematic mapping study of 377 papers from the academic literature, yielding 42 papers analysed against a main research question and ten sub-questions across four thematic axes. We provide the first quantitative characterisation of component adoption, latency, safety coverage, and reproducibility: short-term memory and world-state grounding are near-universal (60% and 69%), whereas long-term memory (31%), reflection (38%"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.05900","title":"Weaver: Weaving Preference Evidence through Incremental Reasoning for Personalized Retrieval-Augmented Generation","url":"https://arxiv.org/abs/2611.05900","tags":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"date":"2026-11-05","authors":["Linyao Zheng","Zhifang Mao","Xuhang Shi"],"pdf":"https://arxiv.org/pdf/2611.05900.pdf","arxiv":"https://arxiv.org/abs/2611.05900","abstract":"Personalized retrieval-augmented generation requires extracting and applying user preferences from extended interaction histories. This task is challenging because preference evidence is scattered across past conversations and remains bound to specific temporal and situational contexts. Consequently, isolated fragments rarely provide complete support for a response, while preferences expressed under different conditions are easily conflated. To address these limitations, we propose Weaver, a framework that incrementally weaves memory-conditioned retrieval trajectories with compositional preference reasoning for personalized responses. Weaver operates on a Dual-Layer Retrieval and Reasoning Graph that couples an upper Intent Dependency Graph with a lower Memory-Conditioned Retrieval Trajectory Graph. Dependency Information Gap Tracking represents the information needed to answer the curre"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Multi-Agent","Code Agent","Evaluation","Alignment"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06506","title":"Trace2Eval: Contextualized Evaluation of Coding Agents from Real-World Traces","url":"https://arxiv.org/abs/2611.06506","tags":["Multi-Agent","Code Agent","Evaluation","Alignment"],"date":"2026-11-05","authors":["Ji Shi","Lirong Jie","Lexiao Zou","Yaoming Zhu","Yifan Yang","Xuezhi Cao","Xunliang Cai","Miao Zhang"],"pdf":"https://arxiv.org/pdf/2611.06506.pdf","arxiv":"https://arxiv.org/abs/2611.06506","abstract":"Coding agents are increasingly used in real-world workflows across diverse domains, motivating evaluation grounded in real user tasks. Existing benchmarks, however, largely rely on static public tasks with reference patches or hidden tests. Next-generation coding-agent benchmarks should therefore move beyond correctness on fixed tasks toward continually renewed evaluation of overall artifact quality in real user workflows. We propose Trace2Eval, a dynamically updatable pipeline that constructs benchmarks from real-world interaction trajectories. Trace2Eval employs a multi-agent reconstruction system to analyze the filtered trajectory, recover the original user query, restore the workspace files to their pre-interaction state, and rebuild a trajectory-equivalent execution environment. A candidate agent then executes the reconstructed query to produce an initial artifact. To evaluate these"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Reasoning","Code Agent","Evaluation","Alignment"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06328","title":"EvoCodeAgent: Project-Level Code Generation via Architecture-Code Co-Evolution and Experience-Guided Repair","url":"https://arxiv.org/abs/2611.06328","tags":["Reasoning","Code Agent","Evaluation","Alignment"],"date":"2026-11-05","authors":["Qianhui Zhao","Li Zhang","Fang Liu"],"pdf":"https://arxiv.org/pdf/2611.06328.pdf","arxiv":"https://arxiv.org/abs/2611.06328","abstract":"Project-level code generation aims to automatically synthesize complete software repositories from high-level requirements, producing coherent multi-file systems with well-structured modules and consistent cross-file dependencies. Despite the strong capabilities of large language models (LLMs) in specification understanding and code synthesis, existing approaches still exhibit several critical limitations. First, many methods rely on static architectural designs that cannot adapt during iterative generation, leading to a growing misalignment between architecture and implementation. Second, they lack mechanisms to accumulate and reuse experience across iterations, resulting in recurring errors and reduced efficiency. Third, they often depend on standalone LLM-based evaluation of intermediate artifacts, which suffer from limited transparency and potential unreliability under long-context r"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Post-Training","VLM Training","Hallucination","Evaluation"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06433","title":"DreamRealm: Exploring and Materializing Hallucination Worlds for Trustworthy Vision-Language Models","url":"https://arxiv.org/abs/2611.06433","tags":["Post-Training","VLM Training","Hallucination","Evaluation"],"date":"2026-11-05","authors":["Benlei Cui","Chunyang Chai","Yiliang Zhang","Xiaoqian Xia","Chengwen Yao","Song Li","Longtao Huang","Yuwen Zhai","Haiwen Hong"],"pdf":"https://arxiv.org/pdf/2611.06433.pdf","arxiv":"https://arxiv.org/abs/2611.06433","abstract":"Multimodal large language models (MLLMs) remain prone to visual hallucinations when correct responses depend on subtle visual details. One line of post-training methods constructs visual contrasts through image retrieval, generation, or editing to improve fine-grained perception. However, these contrasts are not built around the model's own hallucinations, making it difficult to ensure that supervision targets its actual perceptual confusions. Another line suppresses hallucinated outputs through response correction or preference learning under fixed image conditions, but leaves the design of supervision signals on the image-input side underexplored. Inspired by how humans correct misconceptions, we introduce DreamRealm, a post-training framework that explores diverse latent hallucinated responses, minimally edits original images to make them valid, and trains the model to assign each res"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Reasoning","Hallucination","Evaluation","Alignment"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06415","title":"Entropogram-guided Visual Realignment Decoding: Capturing the Rhythm of Multimodal Reasoning","url":"https://arxiv.org/abs/2611.06415","tags":["Reasoning","Hallucination","Evaluation","Alignment"],"date":"2026-11-05","authors":["Jiaqi Deng","Zhe Fu","Yakun Chen","Dichang Zhang","Zonghan Wu","Xiaoshui Huang","Huan Huo","Guandong Xu"],"pdf":"https://arxiv.org/pdf/2611.06415.pdf","arxiv":"https://arxiv.org/abs/2611.06415","abstract":"Multimodal large language models (MLLMs) have demonstrated remarkable progress on cross-modal reasoning tasks, yet they continue to suffer from hallucinations in long-chain reasoning processes. In this work, we revisit hallucination in MLLMs from the perspective of reasoning generation dynamics. We argue that entropy is not merely a static measure of uncertainty but a structured signal that reflects how modality information is integrated throughout decoding. Through systematic analysis, we identify two characteristic entropy patterns associated with hallucination behaviors: (1) a generally high-confidence regime corresponds to premature convergence to inappropriate multimodal interactions; and (2) local abrupt entropy transitions are associated with reasoning instability and hallucination onset. Building on these observations, we propose an entropy-aware self-introspective framework for "},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Post-Training","Evaluation","RL for LLM"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06554","title":"RAGAM-AI: A Hybrid Reinforcement Learning based Agentic approach powered by Generative AI for Edge Resource Management","url":"https://arxiv.org/abs/2611.06554","tags":["Post-Training","Evaluation","RL for LLM"],"date":"2026-11-05","authors":["Shreya K. Chari","John S. Vardakas","Kostas Ramantas","Christos Verikoukis"],"pdf":"https://arxiv.org/pdf/2611.06554.pdf","arxiv":"https://arxiv.org/abs/2611.06554","abstract":"Resource management for distributed edge networks hosting different services has been handled efficiently using Reinforcement learning (RL). Reward generalization in complex workflows is still an open issue within the RL realm. Therefore, this work proposes RAGAM-AI, a hybrid framework that combines the capabilities of RL algorithms and Generative-AI (Gen-AI) for powering an Agentic AI workflow that optimizes resource allocation at the Multi-access Edge Computing (MEC) units. This framework further resolves the reward generalization issue by utilizing Large Language Model (LLM) for feedback. A Multi- Agent Soft-Actor Critic (MASAC) using MathΣtral as a reward oracle is implemented for managing resource allocations at the MEC. RAGAM-AI interprets system state information and evaluates multi-objective trade-offs guiding the resource orchestration loop over distributed edge server agents. T"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["VLM Training","Reasoning","Evaluation"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06259","title":"A Systematic Benchmark for Evaluating Multimodal Personalized Reasoning of Vision-Language Models","url":"https://arxiv.org/abs/2611.06259","tags":["VLM Training","Reasoning","Evaluation"],"date":"2026-11-05","authors":["Dohyun Kim","Junyong Lhim","Kwanyong Park"],"pdf":"https://arxiv.org/pdf/2611.06259.pdf","arxiv":"https://arxiv.org/abs/2611.06259","abstract":"People often make decisions by holistically reasoning over heterogeneous forms of personal information. In this paper, we study the relatively underexplored capability of multimodal personalized reasoning in multimodal large language models (MLLMs). To this end, we introduce \\texttt{MPRBench}, a novel and comprehensive benchmark specifically designed to evaluate personalized reasoning across a wide range of tasks and real-world challenges. \\texttt{MPRBench} consists of 12 sub-tasks and additionally supports interpretable analysis of representative error cases. Through extensive experiments, we find that current personalized MLLMs still struggle with personalized reasoning due to several key challenges, including inaccurate recognition of personalized concepts and sensitivity to irrelevant personal information. We hope that MPRBench will stimulate further research on personalized reasonin"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Multi-Agent","Reasoning","Evaluation"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.05953","title":"Graph-Mediated Large Language Model Systems in the Agentic Era: Reasoning, Knowledge, Retrieval, Execution, and Coordination","url":"https://arxiv.org/abs/2611.05953","tags":["Multi-Agent","Reasoning","Evaluation"],"date":"2026-11-05","authors":["Haihui Liu","Yang Chen","Zice Qiu","Yun Zhang","Jialun Zhong","Wenhua Wang","Yanzeng Li","Tian Wang"],"pdf":"https://arxiv.org/pdf/2611.05953.pdf","arxiv":"https://arxiv.org/abs/2611.05953","abstract":"Graphs play an increasingly important role in large language model (LLM) systems, supporting structural reasoning, knowledge grounding, retrieval, and memory. As these systems evolve toward the agentic era, graphs also organize execution dependencies and multi-agent communication, linking intermediate observations and retained information to subsequent decisions. However, understanding their contribution requires distinguishing the function of each graph operation, the component responsible for its computation, and the subsequent use of its output. This survey introduces an operation-level role--locus taxonomy for reasoning, knowledge and evidence, retrieval and memory, execution, and coordination. We compare how graph observations and external computations guide decisions, how memory representations and updates support later tasks, and how dependencies constrain execution and informatio"},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Agentic Search","Reasoning","Evaluation"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06662","title":"Where Search Agents Go Off the Rails: Graph-Grounded Step-Level Verification","url":"https://arxiv.org/abs/2611.06662","tags":["Agentic Search","Reasoning","Evaluation"],"date":"2026-11-05","authors":["Hyeseo Jeon","Seonho Yoo","Jay-Yoon Lee"],"pdf":"https://arxiv.org/pdf/2611.06662.pdf","arxiv":"https://arxiv.org/abs/2611.06662","abstract":"Search-augmented reasoning systems can reach correct answers while making errors in intermediate steps. Reliable auditing must check whether evidence $D$ covers the question $Q$, reasoning $T$ addresses $Q$, and $T$ is grounded in $D$. We introduce GraphRail, which represents requirements, evidence, and reasoning as structured claims and compares them without a generative judge or gold answer. Across three multi-hop QA benchmarks and three reasoning frameworks, GraphRail improves error recall over generative verifiers while remaining stable under stochastic extraction. Its diagnoses can also guide online reasoning, providing a traceable way to detect and correct intermediate errors."},{"announceDate":"2026-11-05","submittedDate":"2026-11-04","topics":["Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"source":"arxiv","id":"arxiv:2611.06110","title":"Beyond Risk Cues: A Mechanism-Level Benchmark and Verifiable Debate for Scam Video Detection on the Web","url":"https://arxiv.org/abs/2611.06110","tags":["Reasoning","Evaluation","Fine-tuning"],"date":"2026-11-05","authors":["Yifan Wang","Junyu Lu","Shun Zhang","Chaozhuo Li","Fanliang Bu","Rong Yin","Lingbin Bu","Changrong Min","Peng Chen"],"pdf":"https://arxiv.org/pdf/2611.06110.pdf","arxiv":"https://arxiv.org/abs/2611.06110","abstract":"Online scam videos pose significant threats to individuals and society. Existing studies primarily focus on binary classification, offering limited insights into how scams work and the reasoning behind detection decisions. Moreover, they often overlook the challenge of distinguishing scam videos from superficially similar non-scam content, such as advertisements, and the robustness of detection models against misleading arguments. These limitations hinder reliable scam video detection. To address these limitations, we introduce MechScam, a benchmark comprising 6,614 videos covering diverse scam mechanisms and non-scam categories. MechScam provides explanations supported by video evidence, annotations of potential scam elements and their context, and misleading arguments constructed from genuine evidence. Recognizing that genuine evidence can still be used to justify misleading conclusion"}],"archive":[],"latestPath":"data/latest.json"};
